/* sfile — "super file": detailed file header decoding.
 *
 * sfile <file> identifies the format (by magic bytes, falling back to the
 * filename extension) and prints a detailed decode of the file header:
 * field names, offsets, sizes and values, in a uniform table.
 *
 * The per-format knowledge lives in formats.h, which is GENERATED by
 * tools/gen_formats.py from the collected C/C++ reference code
 * (tools/all_formats.cpp) plus a curated magic table and hand overrides
 * (tools/overrides.json). The engine itself is generic: it contains no
 * per-format decode logic, only the table walk, the value formatters and
 * the text/XML fallback decoder.
 *
 * Exit codes: 0 identified, 1 usage error, 2 file unreadable, 3 unknown.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <sys/stat.h>

#include "formats.h"

#define HDR_WIN 65536   /* header window: how much of the file we read */
#define HEXDUMP_LEN 64  /* bytes shown for unknown / magic-only formats */

static const char *prog;

/* ---- value readers (respect per-format endianness) ---- */
static uint16_t rd16(const uint8_t *p, int be) {
    return be ? (uint16_t)((p[0] << 8) | p[1]) : (uint16_t)(p[0] | (p[1] << 8));
}
static uint32_t rd32(const uint8_t *p, int be) {
    if (be) return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
                   ((uint32_t)p[2] << 8) | p[3];
    return p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static uint64_t rd64(const uint8_t *p, int be) {
    uint64_t v = 0;
    if (be) { for (int i = 0; i < 8; i++) v = (v << 8) | p[i]; }
    else    { for (int i = 7; i >= 0; i--) v = (v << 8) | p[i]; }
    return v;
}
static float rd_f32(const uint8_t *p, int be) {
    uint32_t u = rd32(p, be);
    float f; memcpy(&f, &u, 4); return f;
}
static double rd_f64(const uint8_t *p, int be) {
    uint64_t u = rd64(p, be);
    double d; memcpy(&d, &u, 8); return d;
}

static int printable_ascii(const uint8_t *p, size_t n) {
    for (size_t i = 0; i < n; i++)
        if (!isprint(p[i]) && p[i] != 0) return 0;
    return 1;
}

static void print_hex(const uint8_t *p, size_t n) {
    for (size_t i = 0; i < n; i++) printf("%02x ", p[i]);
}

/* ---- identification ---- */
static const SFormat *match_magic(const uint8_t *buf, size_t n, const SFormat **cands, int *ncand) {
    const SFormat *best = NULL;
    *ncand = 0;
    for (int i = 0; i < sfile_nformats; i++) {
        const SFormat *f = &sfile_formats[i];
        if (f->magic_len == 0) continue;
        if (f->magic_off + f->magic_len > n) continue;
        if (memcmp(buf + f->magic_off, f->magic, f->magic_len) == 0) {
            if (*ncand < 64) cands[(*ncand)++] = f;
            if (!best || f->magic_len > best->magic_len) best = f;
        }
    }
    return best;
}

static const char *file_ext(const char *path) {
    const char *dot = strrchr(path, '.');
    const char *slash = strrchr(path, '/');
    if (!dot || (slash && dot < slash)) return "";
    return dot;
}

/* case-insensitive extension compare (".7z" vs ".7Z") */
static int ext_eq(const char *a, const char *b) {
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b)) return 0;
        a++; b++;
    }
    return *a == *b;
}

/* ---- text / XML fallback decoder ---- */
static void decode_text(const uint8_t *buf, size_t n) {
    /* XML declaration? */
    if (n >= 5 && memcmp(buf, "<?xml", 5) == 0) {
        printf("Document type: XML\n");
        const uint8_t *end = memchr(buf, '>', n);
        if (end && (size_t)(end - buf) < 200) {
            printf("XML declaration: %.*s>\n", (int)(end - buf), buf);
        }
        /* root element: first '<' after the declaration that is not a comment/PI */
        size_t i = end ? (size_t)(end - buf) + 1 : 5;
        while (i < n && isspace(buf[i])) i++;
        if (i + 1 < n && buf[i] == '<' && buf[i+1] != '?' && buf[i+1] != '!' && buf[i+1] != '/') {
            size_t j = i + 1;
            while (j < n && (isalnum(buf[j]) || buf[j] == '_' || buf[j] == '-' || buf[j] == '.' || buf[j] == ':')) j++;
            printf("Root element: %.*s\n", (int)(j - i - 1), buf + i + 1);
            /* version attribute on the root element */
            const uint8_t *v = (const uint8_t *)memmem(buf + i, n - i, "version=\"", 9);
            if (v && (size_t)(v - buf) < j + 200) {
                const uint8_t *q = memchr(v + 9, '"', n - (size_t)(v - buf) - 9);
                if (q) printf("Version attribute: %.*s\n", (int)(q - v - 9), v + 9);
            }
        }
        return;
    }
    if (n >= 1 && buf[0] == '{') {
        printf("Document type: JSON\n");
        /* first key, if an object */
        const uint8_t *q1 = memchr(buf + 1, '"', n - 1);
        const uint8_t *q2 = q1 ? memchr(q1 + 1, '"', n - (size_t)(q1 - buf) - 1) : NULL;
        if (q1 && q2 && (size_t)(q2 - q1) < 80)
            printf("First key: %.*s\n", (int)(q2 - q1 - 1), q1 + 1);
        return;
    }
    if (n >= 2 && buf[0] == '[') {
        /* a JSON array must start with a value; an INI section header
           like [PHP] starts with a bare word and must not match */
        char c = (char)buf[1];
        if (c == '"' || c == '{' || c == '[' || (c >= '0' && c <= '9') ||
            c == '-' || c == 't' || c == 'f' || c == 'n') {
            printf("Document type: JSON\n");
            return;
        }
    }
    /* plain text: first line */
    printf("Document type: text\n");
    const uint8_t *nl = memchr(buf, '\n', n < 200 ? n : 200);
    size_t linelen = nl ? (size_t)(nl - buf) : (n < 200 ? n : 200);
    while (linelen > 0 && (buf[linelen-1] == '\r' || buf[linelen-1] == '\n')) linelen--;
    printf("First line: %.*s\n", (int)linelen, buf);
}

/* ---- main decode ---- */
static void decode_binary(const SFormat *f, const uint8_t *buf, size_t n, long fsize) {
    printf("Header (%s-endian):\n", f->endian ? "big" : "little");
    printf("  %-8s %-6s %-28s %s\n", "offset", "size", "field", "value");
    for (int i = 0; i < f->nfields; i++) {
        const SField *fl = &f->fields[i];
        if (fl->offset + fl->size > (uint32_t)n) {
            printf("  %-8u %-6u %-28s (beyond header window / EOF)\n",
                   fl->offset, fl->size, fl->name);
            continue;
        }
        const uint8_t *p = buf + fl->offset;
        printf("  %-8u %-6u %-28s ", fl->offset, fl->size, fl->name);
        switch (fl->kind) {
        case FK_U8:  printf("%u\n", p[0]); break;
        case FK_U16: printf("%u\n", rd16(p, f->endian)); break;
        case FK_U32: printf("%u\n", rd32(p, f->endian)); break;
        case FK_U64: printf("%llu\n", (unsigned long long)rd64(p, f->endian)); break;
        case FK_I8:  printf("%d\n", (int8_t)p[0]); break;
        case FK_I16: printf("%d\n", (int16_t)rd16(p, f->endian)); break;
        case FK_I32: printf("%d\n", (int32_t)rd32(p, f->endian)); break;
        case FK_I64: printf("%lld\n", (long long)(int64_t)rd64(p, f->endian)); break;
        case FK_F32: printf("%g\n", (double)rd_f32(p, f->endian)); break;
        case FK_F64: printf("%g\n", rd_f64(p, f->endian)); break;
        case FK_ASCII:
            if (printable_ascii(p, fl->size)) {
                /* trim at first NUL */
                size_t m = 0;
                while (m < fl->size && p[m]) m++;
                printf("\"%.*s\"\n", (int)m, p);
            } else {
                print_hex(p, fl->size); printf("\n");
            }
            break;
        case FK_BYTES:
        default:
            print_hex(p, fl->size); printf("\n"); break;
        }
    }
    (void)fsize;
}

static void usage(void) {
    fprintf(stderr, "Usage: %s <file> [--list]\n", prog);
    fprintf(stderr, "  sfile identifies a file's format and decodes its header.\n");
    fprintf(stderr, "  --list   list all known formats (task, extension, name, derivation is in formats.json)\n");
}

static int list_formats(void) {
    printf("%-6s %-8s %s\n", "task", "ext", "name");
    for (int i = 0; i < sfile_nformats; i++) {
        const SFormat *f = &sfile_formats[i];
        printf("%-6d %-8s %s\n", f->task, f->ext, f->name);
    }
    printf("%d formats\n", sfile_nformats);
    return 0;
}

int main(int argc, char **argv) {
    prog = argv[0];
    if (argc < 2) { usage(); return 1; }
    if (strcmp(argv[1], "--list") == 0) return list_formats();
    if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) { usage(); return 0; }
    const char *path = argv[1];

    struct stat st;
    if (stat(path, &st) != 0) { perror(path); return 2; }
    FILE *fp = fopen(path, "rb");
    if (!fp) { perror(path); return 2; }
    size_t cap = st.st_size < HDR_WIN ? (size_t)st.st_size : HDR_WIN;
    uint8_t *buf = malloc(cap ? cap : 1);
    if (!buf) { fclose(fp); return 2; }
    size_t n = fread(buf, 1, cap, fp);
    fclose(fp);

    printf("File: %s (%lld bytes)\n", path, (long long)st.st_size);

    const SFormat *cands[64];
    int ncand = 0;
    const SFormat *best = match_magic(buf, n, cands, &ncand);
    const SFormat *fmt = best;
    const char *how = "magic";

    if (!fmt) {
        /* extension fallback */
        const char *ext = file_ext(path);
        if (*ext) {
            for (int i = 0; i < sfile_nformats; i++) {
                if (ext_eq(sfile_formats[i].ext, ext)) { fmt = &sfile_formats[i]; break; }
            }
            if (fmt) how = "extension";
        }
    } else if (ncand > 1) {
        /* several formats share this magic (e.g. PK zip): prefer the one
           whose extension matches the filename */
        const char *ext = file_ext(path);
        if (*ext) {
            for (int i = 0; i < ncand; i++) {
                if (ext_eq(cands[i]->ext, ext)) { fmt = cands[i]; break; }
            }
        }
    }

    if (!fmt) {
        printf("Format: unknown (no magic match, no known extension)\n");
        printf("First %d bytes:\n  ", HEXDUMP_LEN);
        print_hex(buf, n < HEXDUMP_LEN ? n : HEXDUMP_LEN);
        printf("\n");
        free(buf);
        return 3;
    }

    printf("Format: %s (%s) — task %d\n", fmt->name, fmt->ext, fmt->task);
    printf("Identified by: %s\n", how);
    if (fmt->magic_len) {
        printf("Magic: ");
        print_hex((const uint8_t *)fmt->magic, fmt->magic_len);
        printf("at offset %u\n", fmt->magic_off);
    }
    if (ncand > 1) {
        printf("Note: %d formats share this magic; extension disambiguated to %s.\n", ncand, fmt->ext);
        printf("Other candidates:");
        for (int i = 0; i < ncand; i++)
            if (cands[i] != fmt) printf(" %s (task %d)", cands[i]->ext, cands[i]->task);
        printf("\n");
    }

    if (fmt->kind == FMT_TEXT) {
        decode_text(buf, n);
    } else if (fmt->nfields > 0) {
        decode_binary(fmt, buf, n, st.st_size);
    } else {
        printf("Header layout: not derived for this format (see formats.json, derivation: %s).\n",
               fmt->kind == FMT_UNKNOWN ? "unknown" : "magic-only");
        printf("First %d bytes:\n  ", HEXDUMP_LEN);
        print_hex(buf, n < HEXDUMP_LEN ? n : HEXDUMP_LEN);
        printf("\n");
    }
    free(buf);
    return 0;
}
